import{_ as e,o as a,c as o,ae as i}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"TMX Editor","description":"","frontmatter":{},"headers":[],"relativePath":"tools/tmx-editor.md","filePath":"tools/tmx-editor.md"}'),r={name:"tools/tmx-editor.md"};function n(l,t,s,m,d,c){return a(),o("div",null,t[0]||(t[0]=[i('<h1 id="tmx-editor" tabindex="-1">TMX Editor <a class="header-anchor" href="#tmx-editor" aria-label="Permalink to &quot;TMX Editor&quot;">​</a></h1><p>Supervertaler includes a built-in TMX editor for inspecting and editing TMX translation memories.</p><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to &quot;Where to find it&quot;">​</a></h2><ul><li>Go to the <strong>Tools</strong> tab → <strong>✏️ TMX Editor</strong>.</li></ul><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li>Open, edit, and save TMX files.</li><li>Search and filter by source/target text.</li><li>Edit TMX header metadata.</li><li>Run basic validation and view statistics.</li><li>Perform bulk operations (for example: delete entries, copy source → target).</li></ul><h2 id="common-workflows" tabindex="-1">Common workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common workflows&quot;">​</a></h2><h3 id="clean-up-a-tmx-before-importing" tabindex="-1">Clean up a TMX before importing <a class="header-anchor" href="#clean-up-a-tmx-before-importing" aria-label="Permalink to &quot;Clean up a TMX before importing&quot;">​</a></h3><ol><li>Open the TMX in <strong>✏️ TMX Editor</strong>.</li><li>Fix any obvious formatting issues (wrong language, empty segments, etc.).</li><li>Save the TMX.</li><li>Import it into your project via <a href="./../translation-memory/importing-tmx.html">Importing TMX files</a>.</li></ol><h3 id="remove-unwanted-tags" tabindex="-1">Remove unwanted tags <a class="header-anchor" href="#remove-unwanted-tags" aria-label="Permalink to &quot;Remove unwanted tags&quot;">​</a></h3><p>If you’re trying to simplify a TMX that contains formatting or CAT-tool tags, you can remove them before importing.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>TMX is just XML — some tags are real inline markup (TMX/XLIFF-style), others are literal text like <code>&amp;lt;b&amp;gt;...&amp;lt;/b&amp;gt;</code>. Cleaning tags can improve matching, but it can also remove important formatting. If you’re unsure, test on a copy first.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../translation-memory/importing-tmx.html">Importing TMX files</a></li><li><a href="./../translation-memory/basics.html">Translation memory</a></li></ul>',14)]))}const p=e(r,[["render",n]]);export{u as __pageData,p as default};
